<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {Workflow,Check,ArrowLeft,ArrowUpRight,ShieldCheck,FileText,MessagesSquare,Layers,AlertCircle} from '@lucide/vue'
const props=defineProps<{scenario:string}>()
const stage=ref('review'),section=ref('overview'),resume=ref(true),scope=ref(true),confirmed=ref(false)
const blocked=computed(()=>['Disconnected','Read only','Permission denied','Changed version','Missing source','Conflict'].includes(props.scenario))
watch(()=>props.scenario,()=>{stage.value='review';confirmed.value=false})
watch([resume,scope],()=>{confirmed.value=false})
function approve(){if(!blocked.value&&confirmed.value){stage.value='running';section.value='overview'}}
</script>
<template><section class="handoff-preview"><header class="pv-between"><div><p class="pv-eyebrow">BLUEPRINT HANDOFF · PV-05 / r1</p><h1>Review a blueprint run</h1><p class="pv-muted">One confirmed version. One run. Results return to this conversation.</p></div><span class="pv-badge">{{stage==='review'?'Awaiting your confirmation':stage==='running'?'Running':stage==='declined'?'Declined':'Completed'}}</span></header>
<div v-if="blocked" class="launch-warning" role="alert"><AlertCircle :size="18"/><span>{{scenario==='Changed version'?'The blueprint or a bound resource changed. Review a new proposal; this version cannot run.':scenario==='Missing source'?'The source conversation is unavailable. This handoff cannot be used.':`${scenario}. Starting this run is unavailable.`}}</span></div>
<div class="launch-shell"><nav aria-label="Run review sections"><button v-for="item in [{id:'overview',label:'Run overview',icon:Workflow},{id:'resources',label:'Bound versions',icon:Layers},{id:'handoff',label:'Conversation handoff',icon:MessagesSquare}]" :key="item.id" class="btn" :class="{'btn-primary':section===item.id}" @click="section=item.id"><component :is="item.icon" :size="16"/>{{item.label}}</button></nav>
<div v-if="section==='overview'" class="launch-body"><div class="launch-title"><Workflow :size="25"/><div><h2>Inspect and validate workspace</h2><p class="pv-muted">blueprints/workspace-review.blueprint · version 12</p></div></div><div class="launch-columns"><div><h3>What this run will do</h3><p>Read the selected project files, apply the review checklist, and produce a verification summary.</p><dl><dt>Parent conversation</dt><dd>Review the workspace · fixed message endpoint 18</dd><dt>Execution scope</dt><dd>Current workspace · existing permission checks</dd><dt>Inputs</dt><dd>Project checklist + your selected review template</dd><dt>Bound version</dt><dd><code>bp:92af…481d</code> · exact content and layout</dd></dl></div><aside><ShieldCheck :size="20"/><h3>Completion policy</h3><label><input v-model="resume" type="checkbox" :disabled="stage!=='review'"/>Resume this conversation when the run finishes</label><p v-if="resume">Up to 2 additional turns · 120,000 remaining tokens · expires in 60 minutes</p><p v-else>Keep the run result for review. No automatic model turn.</p><p class="pv-muted">Stopping the blueprint records the result and waits for your decision. It will not automatically restart.</p></aside></div></div>
<div v-else-if="section==='resources'" class="launch-body"><h2>Versions you are approving</h2><p class="pv-muted">Any change invalidates this proposal.</p><table><thead><tr><th>Resource</th><th>Scope / version</th><th>Binding</th></tr></thead><tbody><tr><td><FileText :size="15"/>Workspace review</td><td>Blueprint · v12</td><td><code>92af…481d</code></td></tr><tr><td>Review checklist</td><td>Project Prompt · v3</td><td>Selected snapshot</td></tr><tr><td>Writing style</td><td>Personal Prompt · v2</td><td>Only this selected resource</td></tr><tr><td>CollectFindings</td><td>Workspace function · v5</td><td>Frozen body digest</td></tr><tr><td>Built-in node catalog</td><td>Current host catalog</td><td>Exact catalog digest</td></tr></tbody></table><p class="pv-muted">No other personal resources are included.</p></div>
<div v-else class="launch-body"><h2>What crosses into execution</h2><div class="launch-columns"><div><h3>Your goal and constraints</h3><p>Inspect the selected workspace and report verification evidence. Keep existing changes. Do not publish or run paid services.</p><h3>Model summary</h3><p class="pv-muted">The proposed run groups the file checks and verification results. This summary is model-authored and does not grant permissions.</p></div><aside><h3>Source access</h3><label><input v-model="scope" type="checkbox" :disabled="stage!=='review'"/>Allow bounded reading up to message 18 in this conversation</label><p>Original roles remain visible. Later messages and other conversations are excluded.</p><button class="btn" @click="section='overview'"><ArrowLeft :size="15"/>Return to run overview</button></aside></div></div>
<footer v-if="stage==='review'" class="launch-footer"><label><input v-model="confirmed" type="checkbox" :disabled="blocked"/>I approve this version, the handoff scope and completion policy</label><div class="pv-between"><span class="pv-muted">The current chat finishes saving before execution starts.</span><div class="pv-actions"><button class="btn" @click="stage='declined'">Decline</button><button class="btn btn-primary" :disabled="blocked||!confirmed" @click="approve">Confirm and run <ArrowUpRight :size="15"/></button></div></div></footer>
<footer v-else class="launch-footer"><div class="pv-between"><span><Check :size="16"/>{{stage==='running'?'The exact intent is bound to run 6e21…b9f0.':stage==='declined'?'Proposal declined. Nothing was started.':'Result saved to the original conversation.'}}</span><div class="pv-actions"><button v-if="stage==='running'" class="btn" @click="stage='completed'">Simulate completion</button><button class="btn" @click="stage='review';confirmed=false">Reset preview</button></div></div><p class="pv-muted">Completion updates the result card without changing your current page.</p></footer></div></section></template>
